/**
 * Common reusable schemas (email, slug, URL, UUID, pagination, …) expressed
 * against the `SchemaValidator` contract via `defineSchema`.
 *
 * Each schema is a lazy getter. The `CommonSchemas` object exposes them via
 * property accessors to preserve the existing call shape
 * (`CommonSchemas.email.parse(x)` continues to work).
 *
 * @module schemas/common
 */
import { MAX_URL_LENGTH_FOR_VALIDATION } from "../utils/constants/index.js";
import { defineSchema } from "./define.js";
import { getTimestampSchema } from "./primitives.js";
const SLUG_PATTERN = /^[a-z0-9-]+$/;
const E164_PHONE_NUMBER_PATTERN = /^\+?[1-9]\d{1,14}$/;
const MAX_EMAIL_LENGTH = 255;
const MAX_SLUG_LENGTH = 100;
const DEFAULT_PAGE_NUMBER = 1;
const DEFAULT_PAGE_LIMIT = 10;
const MAX_PAGE_LIMIT = 100;
const MAX_SAFE_INTEGER_DIGITS = String(Number.MAX_SAFE_INTEGER).length;
const DECIMAL_INTEGER_PATTERN = /^\d+$/;
const STRONG_PASSWORD_MIN_LENGTH = 8;
export const getEmailSchema = defineSchema((v) => v.string().max(MAX_EMAIL_LENGTH).email());
export const getUuidSchema = defineSchema((v) => v.string().uuid());
export const getSlugSchema = defineSchema((v) => v.string().min(1).max(MAX_SLUG_LENGTH).regex(SLUG_PATTERN));
export const getUrlSchema = defineSchema((v) => v.string().max(MAX_URL_LENGTH_FOR_VALIDATION).url());
export const getPhoneNumberSchema = defineSchema((v) => v.string().regex(E164_PHONE_NUMBER_PATTERN));
export const getPaginationSchema = defineSchema((v) => {
    const numericQueryParameter = (numberSchema) => v.union([
        v
            .string()
            .max(MAX_SAFE_INTEGER_DIGITS)
            .regex(DECIMAL_INTEGER_PATTERN)
            .transform((value) => Number(value))
            .pipe(numberSchema),
        numberSchema,
    ]);
    const pageNumber = v.number().int().positive();
    const pageLimit = v.number().int().positive().max(MAX_PAGE_LIMIT);
    return v.object({
        page: numericQueryParameter(pageNumber).default(DEFAULT_PAGE_NUMBER),
        limit: numericQueryParameter(pageLimit).default(DEFAULT_PAGE_LIMIT),
        sort: v.string().optional(),
        order: v.enum(["asc", "desc"]).optional(),
    });
});
export const getDateRangeSchema = defineSchema((v) => v
    .object({
    from: getTimestampSchema(),
    to: getTimestampSchema(),
})
    .refine(({ from, to }) => new Date(from) <= new Date(to), {
    message: "From date must be before or equal to To date",
}));
export const getStrongPasswordSchema = defineSchema((v) => v
    .string()
    .min(STRONG_PASSWORD_MIN_LENGTH, `Password must be at least ${STRONG_PASSWORD_MIN_LENGTH} characters`)
    .regex(/[A-Z]/, "Password must contain at least one uppercase letter")
    .regex(/[a-z]/, "Password must contain at least one lowercase letter")
    .regex(/[0-9]/, "Password must contain at least one number")
    .regex(/[^A-Za-z0-9]/, "Password must contain at least one special character"));
/**
 * Lazy-getter object that preserves the `CommonSchemas.email` call shape.
 * Each access returns the cached `Schema<T>` (memoized inside `defineSchema`),
 * so chained calls like `CommonSchemas.email.parse(x)` work as before.
 */
export const CommonSchemas = {
    get email() {
        return getEmailSchema();
    },
    get uuid() {
        return getUuidSchema();
    },
    get slug() {
        return getSlugSchema();
    },
    get url() {
        return getUrlSchema();
    },
    get phoneNumber() {
        return getPhoneNumberSchema();
    },
    get pagination() {
        return getPaginationSchema();
    },
    get dateRange() {
        return getDateRangeSchema();
    },
    get strongPassword() {
        return getStrongPasswordSchema();
    },
};
